--
-- Name: monthlytime; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."monthlytime" (
    "pactstaffid" character varying(50) NOT NULL,
    "timecode" character varying(50) NOT NULL,
    "month" double precision NOT NULL,
    "parentproject" character varying(20) NOT NULL,
    "workgroup" character varying(50),
    "hours" double precision,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: tblstaffjob; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tblstaffjob" (
    "staffid" character varying(50) NOT NULL,
    "jobcode" character varying(20) NOT NULL,
    "plannedhours" double precision DEFAULT 0 NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: all_staff_project; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."all_staff_project" AS
 SELECT "tblstaffjob"."staffid" AS "pactid",
    "tblstaffjob"."jobcode" AS "parentproject",
    "tblstaffjob"."fpsyear"
   FROM "fps"."tblstaffjob"
UNION
 SELECT "monthlytime"."pactstaffid" AS "pactid",
    "monthlytime"."parentproject",
    "monthlytime"."fpsyear"
   FROM "fps"."monthlytime"
  GROUP BY "monthlytime"."pactstaffid", "monthlytime"."parentproject", "monthlytime"."fpsyear";


--
-- Name: tlkpproject; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tlkpproject" (
    "parentproject" character varying(20) NOT NULL,
    "projecttitle" character varying(200) NOT NULL,
    "program" character varying(10) NOT NULL,
    "customer" character varying(50) NOT NULL,
    "manager" character varying(50),
    "transferincome" "money" NOT NULL,
    "custincome" "money" NOT NULL,
    "wip_eoy" "money" DEFAULT 0,
    "wip_limit" "money",
    "wip_current" "money",
    "projectstatus" character varying(50) NOT NULL,
    "costbookno" character varying(50),
    "datecreated" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "feccost" "money" DEFAULT 0,
    "profit" "money" DEFAULT 0,
    "budget_cvl" "money" DEFAULT 0,
    "datecosted" timestamp without time zone,
    "disease" character varying(50) NOT NULL,
    "contract" character varying(10) DEFAULT 0 NOT NULL,
    "projectparent" character varying(50),
    "shorttitle" character varying(30),
    "caseworksub" numeric(5,4),
    "pvsincome" "money",
    "plancaseworkdebit" "money",
    "finished" smallint DEFAULT 0,
    "owningrc" character varying(50),
    "comments" "text",
    "carryover" "money",
    "carryoverseed" "money",
    "isdefraproject" smallint NOT NULL,
    "costcentre" double precision,
    "oracleprojectcode" character varying(50),
    "subaccountcode" character varying(50),
    "projectgroup" character varying(50),
    "incomeaccountcode" character varying(50) NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: workgroup; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."workgroup" (
    "workgroup" character varying(50) NOT NULL,
    "profitcentre" character varying(50) NOT NULL,
    "costcentre" double precision,
    "owner" character varying(50),
    "description" character varying(45),
    "centraloverhead" "money" DEFAULT 0,
    "sendemail" smallint,
    "cos90" smallint,
    "costcentreold" double precision,
    "email_recipient" character varying(50),
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: all_wg_project; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."all_wg_project" AS
 SELECT "workgroup"."workgroup",
    "tlkpproject"."parentproject" AS "project",
    "tlkpproject"."fpsyear"
   FROM ("fps"."workgroup"
     JOIN "fps"."tlkpproject" ON (("workgroup"."fpsyear" = "tlkpproject"."fpsyear")));


