--
-- Name: timecostcalcs; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."timecostcalcs" (
    "workgroup" character varying(50) NOT NULL,
    "jobcode" character varying(50) NOT NULL,
    "project" character varying(20) NOT NULL,
    "month" double precision NOT NULL,
    "staffid" character varying(50) NOT NULL,
    "gradecode" character varying(10),
    "name" character varying(50),
    "chargerate" "money",
    "class" character varying(255),
    "time" double precision,
    "cost" double precision,
    "division" character varying(10),
    "jobcodeold" character varying(14),
    "pay" "money",
    "nonpay" "money",
    "overhead" "money",
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: pandoratimecostcalcs; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."pandoratimecostcalcs" AS
 SELECT DISTINCT "tc"."workgroup",
    "tc"."jobcode",
    "tc"."project",
    "tc"."month",
    "tc"."staffid",
    "tc"."gradecode",
    "tc"."name",
    "tc"."chargerate",
    "tc"."class",
    "tc"."time",
    "tc"."cost",
    "tc"."division",
    "tc"."jobcodeold",
    "tc"."pay",
    "tc"."nonpay",
    "tc"."overhead",
    "tc"."fpsyear",
    "u"."user_id",
    "u"."dt2username",
    "u"."useremail"
   FROM (("fps"."timecostcalcs" "tc"
     JOIN "fps"."tbluser_workgroup" "uw" ON ((("tc"."workgroup")::"text" = ("uw"."workgroup")::"text")))
     JOIN "fps"."tblusers" "u" ON (("uw"."user_id" = "u"."user_id")));


