    "profitcentrehead" character varying(50),
    "divisionid" integer DEFAULT 0,
    "email_recipient" character varying(50),
    "timesheetlayout" smallint,
    "timesheet" integer,
    "outputsheet" integer,
    "pactcoordinatoremailname" character varying(50),
    "highlevelsummary" "bytea"
