--
-- Name: vapphours; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vapphours" AS
 SELECT "tblwgemployee"."workgroupgrade",
    "tblstaffjob"."fpsyear",
    "sum"("tblstaffjob"."plannedhours") AS "sumofplannedhours"
   FROM ((("fps"."tlkpproject"
     JOIN "fps"."tblstaffjob" ON (((("tlkpproject"."parentproject")::"text" = ("tblstaffjob"."jobcode")::"text") AND ("tlkpproject"."fpsyear" = "tblstaffjob"."fpsyear"))))
     JOIN "fps"."tblwgemployee" ON (((("tblstaffjob"."staffid")::"text" = ("tblwgemployee"."pactid")::"text") AND ("tblstaffjob"."fpsyear" = "tblwgemployee"."fpsyear"))))
     JOIN "fps"."tlkpprogram" ON (((("tlkpproject"."program")::"text" = ("tlkpprogram"."programno")::"text") AND ("tlkpproject"."fpsyear" = "tlkpprogram"."fpsyear"))))
  WHERE ((("tlkpproject"."program")::"text" <> 'ZT_Prog'::"text") AND (("tlkpproject"."projectstatus")::"text" = 'approved'::"text") AND (("tlkpprogram"."sector_name")::"text" = 'Charge'::"text"))
  GROUP BY "tblwgemployee"."workgroupgrade", "tblstaffjob"."fpsyear";


--
-- Name: vqrytbidsum; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vqrytbidsum" AS
 SELECT "pc"."profitcentre",
    "b"."fpsyear",
    "sum"("b"."genbid") AS "sumofgenbid",
    "u"."user_id",
    "u"."dt2username",
    "u"."useremail"
   FROM (((("fps"."tblkpprofitcentre" "pc"
     JOIN "fps"."workgroup" "w" ON ((("pc"."profitcentre")::"text" = ("w"."profitcentre")::"text")))
     JOIN "fps"."tblbid" "b" ON (((("w"."workgroup")::"text" = ("b"."workgroup")::"text") AND ("w"."fpsyear" = "b"."fpsyear"))))
     JOIN "fps"."tbluser_profitcentre" "upc" ON ((("pc"."profitcentre")::"text" = ("upc"."profitcentre")::"text")))
     JOIN "fps"."tblusers" "u" ON (("upc"."user_id" = "u"."user_id")))
  GROUP BY "pc"."profitcentre", "b"."fpsyear", "u"."user_id", "u"."dt2username", "u"."useremail";


--
-- Name: vstaffjobhours; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vstaffjobhours" AS
 SELECT "tblstaffjob"."staffid",
    "tblstaffjob"."fpsyear",
    "sum"("tblstaffjob"."plannedhours") AS "plannedhours"
   FROM (("fps"."tblstaffjob"
     JOIN "fps"."tlkpproject" ON (((("tblstaffjob"."jobcode")::"text" = ("tlkpproject"."parentproject")::"text") AND ("tblstaffjob"."fpsyear" = "tlkpproject"."fpsyear"))))
     JOIN "fps"."tlkpprogram" ON (((("tlkpproject"."program")::"text" = ("tlkpprogram"."programno")::"text") AND ("tlkpproject"."fpsyear" = "tlkpprogram"."fpsyear"))))
  WHERE ((("tlkpproject"."program")::"text" <> 'zt_prog'::"text") AND (("tlkpprogram"."sector_name")::"text" = 'Charge'::"text"))
  GROUP BY "tblstaffjob"."staffid", "tblstaffjob"."fpsyear";


--
-- Name: workgroupgrade; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."workgroupgrade" (
    "wggrade" character varying(50) NOT NULL,
    "profitcentregrade" character varying(20) NOT NULL,
    "gradecode" character varying(10) NOT NULL,
    "workgroup" character varying(50) NOT NULL,
    "chargeratewg" "money",
    "directratewg" "money" DEFAULT 0,
    "payratewg" "money" DEFAULT 0,
    "nprwg" "money" DEFAULT 0,
    "ohrwg" "money" DEFAULT 0,
    "avsalary" "money" DEFAULT 0,
    "hrschangedby" character varying(50),
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: qryfrmtimesellerpc_map; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryfrmtimesellerpc_map" AS
 SELECT "tblkpprofitcentre"."conttarget",
    "profitcentregrade"."profitcentre" AS "sellingpc",
    "profitcentregrade"."chargerate",
    "profitcentregrade"."ohr",
    "vqrytbidsum"."sumofgenbid",
    "workgroupgrade"."workgroup",
    "workgroupgrade"."profitcentregrade" AS "profitcentregrade_col",
    "workgroupgrade"."wggrade",
    "vapphours"."sumofplannedhours" AS "apphours",
    "sum"("vstaffjobhours"."plannedhours") AS "hrs",
    "sum"("tblwgemployee"."hrsavail") AS "avhrs",
    ("sum"("vstaffjobhours"."plannedhours") * "profitcentregrade"."chargerate") AS "fec",
    ("vapphours"."sumofplannedhours" * "profitcentregrade"."chargerate") AS "appfec",
    ("profitcentregrade"."ohr" * "sum"("vstaffjobhours"."plannedhours")) AS "contribution"
   FROM (("fps"."vapphours"
     RIGHT JOIN ((("fps"."tblkpprofitcentre"
     JOIN ("fps"."profitcentregrade"
     LEFT JOIN "fps"."vqrytbidsum" ON ((("profitcentregrade"."profitcentre")::"text" = ("vqrytbidsum"."profitcentre")::"text"))) ON ((("tblkpprofitcentre"."profitcentre")::"text" = ("profitcentregrade"."profitcentre")::"text")))
     JOIN "fps"."workgroupgrade" ON ((("profitcentregrade"."pcgrade")::"text" = ("workgroupgrade"."profitcentregrade")::"text")))
     JOIN "fps"."tblwgemployee" ON ((("workgroupgrade"."wggrade")::"text" = ("tblwgemployee"."workgroupgrade")::"text"))) ON ((("vapphours"."workgroupgrade")::"text" = ("workgroupgrade"."wggrade")::"text")))
     LEFT JOIN "fps"."vstaffjobhours" ON ((("tblwgemployee"."pactid")::"text" = ("vstaffjobhours"."staffid")::"text")))
  GROUP BY "tblkpprofitcentre"."conttarget", "profitcentregrade"."profitcentre", "profitcentregrade"."chargerate", "profitcentregrade"."ohr", "vqrytbidsum"."sumofgenbid", "workgroupgrade"."workgroup", "workgroupgrade"."profitcentregrade", "workgroupgrade"."wggrade", "vapphours"."sumofplannedhours";


--
-- Name: qryjobmonth_invoices; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_invoices" AS
 SELECT "projectparent",
    "month",
    "fpsyear",
    "sum"("amount") AS "sumofamount1",
    "sum"("costofwork") AS "workcost"
   FROM "fps"."proj_invoice"
  GROUP BY "projectparent", "month", "fpsyear";


--
-- Name: qryjobmonth_subcontracts1; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_subcontracts1" AS
 SELECT DISTINCT "project",
    "month",
    "acctcode",
    "fpsyear",
    "sum"(("amount")::numeric) AS "total",
        CASE
            WHEN (("acctcode")::"text" = ANY (ARRAY[('LargeAnimals'::character varying)::"text", ('SmallAnimals'::character varying)::"text", ('Mice'::character varying)::"text"])) THEN "sum"(("amount")::numeric)
            ELSE (0)::numeric
        END AS "animals1",
        CASE
            WHEN (("acctcode")::"text" = ANY (ARRAY[('LargeAnimals'::character varying)::"text", ('SmallAnimals'::character varying)::"text", ('Mice'::character varying)::"text"])) THEN (0)::numeric
            ELSE "sum"(("amount")::numeric)
        END AS "other1"
   FROM "fps"."proj_subcontract"
  GROUP BY "project", "month", "acctcode", "fpsyear";


--
-- Name: qryjobmonth_subcontracts; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_subcontracts" AS
 SELECT "project",
    "month",
    "fpsyear",
    "sum"("animals1") AS "animals",
    "sum"("other1") AS "other",
    ("sum"("animals1") + "sum"("other1")) AS "total"
   FROM "fps"."qryjobmonth_subcontracts1"
  GROUP BY "project", "month", "fpsyear";


--
-- Name: tlkptestcapability; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tlkptestcapability" (
