--
-- Name: vpacttlkptestcapability; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vpacttlkptestcapability" AS
 SELECT "testcode",
    "workgroup",
    "planportfolio",
    "smscode",
    (("testcode")::"text" || ("workgroup")::"text") AS "wgtestcode",
    "fpsyear"
   FROM "fps"."tlkptestcapability";


--
-- Name: qryjobmonth_tctransfers; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_tctransfers" AS
 SELECT "vpacttlkptestcapability"."planportfolio" AS "project",
    "monthlyoutput"."month",
    "monthlyoutput"."testcode",
    "monthlyoutput"."volume",
    "tlkptestreqmt"."unitprice" AS "intunitprice",
    "monthlyoutput"."fpsyear",
    "sum"(("monthlyoutput"."volume" * "tlkptestreqmt"."unitprice")) AS "transfercost"
   FROM (("fps"."monthlyoutput"
     JOIN "fps"."tlkptestreqmt" ON (((("monthlyoutput"."testcode")::"text" = ("tlkptestreqmt"."testcode")::"text") AND (("monthlyoutput"."buyer")::"text" = ("tlkptestreqmt"."buyer")::"text") AND ("monthlyoutput"."fpsyear" = "tlkptestreqmt"."fpsyear"))))
     JOIN "fps"."vpacttlkptestcapability" ON (((("tlkptestreqmt"."buyer")::"text" = "vpacttlkptestcapability"."wgtestcode") AND ("tlkptestreqmt"."fpsyear" = "vpacttlkptestcapability"."fpsyear"))))
  GROUP BY "vpacttlkptestcapability"."planportfolio", "monthlyoutput"."month", "monthlyoutput"."testcode", "monthlyoutput"."volume", "tlkptestreqmt"."unitprice", "monthlyoutput"."fpsyear";


--
-- Name: qryjobmonth_time; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_time" AS
 SELECT DISTINCT "project",
    "month",
    "fpsyear",
    "sum"("cost") AS "sumofcost",
    "sum"("time") AS "sumofhours",
    "sum"("pay") AS "sumofpayrate"
   FROM "fps"."timecostcalcs"
  GROUP BY "project", "month", "fpsyear";


--
-- Name: qryjobmonth_totprofile; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_totprofile" AS
 SELECT DISTINCT "project",
    "fpsyear",
    "sum"("costprofile") AS "sumofcostprofile"
   FROM "fps"."projectmonth"
  GROUP BY "project", "fpsyear";


--
-- Name: testorproduct; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."testorproduct" (
    "itemcode" character varying(20) NOT NULL,
    "itemdescription" character varying(200),
    "testmanager" character varying(50),
    "jobstatus" character varying(2),
    "unitpricevla" "money" DEFAULT 0,
    "priceahvg" "money",
    "owner" character varying(2),
    "chargemethod" character varying(5),
    "shortdescription" character(18),
    "defraunitprice" "money" DEFAULT 0 NOT NULL,
    "fpsyear" integer NOT NULL,
    CONSTRAINT "testorproduct_owner_cannot_be_null" CHECK ((("owner" IS NOT NULL) AND ((("owner")::"text" = 'PT'::"text") OR (("owner")::"text" = 'PA'::"text") OR (("owner")::"text" = 'SD'::"text") OR (("owner")::"text" = 'LT'::"text"))))
)
PARTITION BY LIST ("fpsyear");


--
-- Name: qryjobmonth_transfers1; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_transfers1" AS
 SELECT DISTINCT "monthlyoutput"."buyer" AS "project",
    "monthlyoutput"."month",
    "monthlyoutput"."testcode",
    "monthlyoutput"."volume",
    "tlkptestreqmt"."unitprice" AS "intunitprice",
    "monthlyoutput"."fpsyear",
    "sum"(("monthlyoutput"."volume" * "tlkptestreqmt"."unitprice")) AS "transfercost"
   FROM (("fps"."testorproduct"
     JOIN "fps"."tlkptestreqmt" ON (((("testorproduct"."itemcode")::"text" = ("tlkptestreqmt"."testcode")::"text") AND ("testorproduct"."fpsyear" = "tlkptestreqmt"."fpsyear"))))
     JOIN "fps"."monthlyoutput" ON (((("tlkptestreqmt"."buyer")::"text" = ("monthlyoutput"."buyer")::"text") AND (("tlkptestreqmt"."testcode")::"text" = ("monthlyoutput"."testcode")::"text") AND ("tlkptestreqmt"."fpsyear" = "monthlyoutput"."fpsyear"))))
  GROUP BY "monthlyoutput"."buyer", "monthlyoutput"."month", "monthlyoutput"."testcode", "monthlyoutput"."volume", "tlkptestreqmt"."unitprice", "monthlyoutput"."fpsyear";


--
-- Name: qryjobmonth_transfers2; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_transfers2" AS
 SELECT DISTINCT "project",
    "month",
    "fpsyear",
    "sum"("transfercost") AS "sumoftransfercost"
   FROM "fps"."qryjobmonth_transfers1"
  GROUP BY "project", "month", "fpsyear";


--
-- Name: qryjobmonth_transferunion; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_transferunion" AS
 SELECT "qryjobmonth_tctransfers"."project",
    "qryjobmonth_tctransfers"."month",
    "qryjobmonth_tctransfers"."fpsyear",
    "qryjobmonth_tctransfers"."transfercost"
   FROM "fps"."qryjobmonth_tctransfers"
UNION ALL
 SELECT "qryjobmonth_transfers1"."project",
    "qryjobmonth_transfers1"."month",
    "qryjobmonth_transfers1"."fpsyear",
    "qryjobmonth_transfers1"."transfercost"
   FROM "fps"."qryjobmonth_transfers1";


--
-- Name: qryjobmonth_transferstotal; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonth_transferstotal" AS
 SELECT DISTINCT "project",
    "month",
    "fpsyear",
    "sum"("transfercost") AS "sumoftransfercost"
   FROM "fps"."qryjobmonth_transferunion"
  GROUP BY "project", "month", "fpsyear";


--
-- Name: qrymilestone1; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrymilestone1" AS
 SELECT DISTINCT "project",
    "milestoneref",
    "plandate",
    "actualdate",
    "monthnofin" AS "duemonth",
        CASE
            WHEN ("actualdate" <= "plandate") THEN (1)::numeric
            ELSE (0)::numeric
        END AS "ontimeflag",
        CASE
            WHEN ("actualdate" IS NULL) THEN 0
            ELSE 1
        END AS "completeflag",
    "year",
    "fpsyear"
   FROM "fps"."milestone"
  WHERE (("year")::"text" = '2003/2004'::"text");


--
-- Name: qryjobmonthmilestone; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonthmilestone" AS
 SELECT "project",
    "duemonth",
    "count"("milestoneref") AS "mstonedue",
    "sum"("completeflag") AS "due__done",
    "sum"("ontimeflag") AS "ontime"
   FROM "fps"."qrymilestone1"
  GROUP BY "project", "duemonth";


--
-- Name: qryjobmonthportfoliosales; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryjobmonthportfoliosales" AS
 SELECT DISTINCT "tlkptestcapability"."planportfolio",
    "monthlyoutput"."month",
    "monthlyoutput"."fpsyear",
    "sum"(("tlkptestreqmt"."unitprice" * "monthlyoutput"."volume")) AS "fee"
   FROM ("fps"."tlkptestreqmt"
     JOIN ("fps"."tlkptestcapability"
     JOIN "fps"."monthlyoutput" ON (((("tlkptestcapability"."workgroup")::"text" = ("monthlyoutput"."workgroup")::"text") AND (("tlkptestcapability"."testcode")::"text" = ("monthlyoutput"."testcode")::"text") AND ("tlkptestcapability"."fpsyear" = "monthlyoutput"."fpsyear")))) ON (((("tlkptestreqmt"."buyer")::"text" = ("monthlyoutput"."buyer")::"text") AND (("tlkptestreqmt"."testcode")::"text" = ("monthlyoutput"."testcode")::"text") AND ("tlkptestreqmt"."fpsyear" = "monthlyoutput"."fpsyear"))))
  GROUP BY "tlkptestcapability"."planportfolio", "monthlyoutput"."month", "monthlyoutput"."fpsyear";


--
-- Name: qryprojectmonthcw; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryprojectmonthcw" AS
 SELECT DISTINCT "projectmonth"."project",
    "projectmonth"."monthno",
    "projectmonth"."fpsyear",
    ("tlkpproject"."plancaseworkdebit" / 12) AS "cwdebit",
    (("tlkpproject"."transferincome" * ("tlkpproject"."caseworksub")::double precision) / 12) AS "cwcredit"
   FROM ("fps"."tlkpproject"
     JOIN "fps"."projectmonth" ON (((("tlkpproject"."parentproject")::"text" = ("projectmonth"."project")::"text") AND ("tlkpproject"."fpsyear" = "projectmonth"."fpsyear"))));


--
-- Name: tblperiod; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tblperiod" (
    "periodname" character varying(50) NOT NULL,
    "periodtype" character varying(50),
    "startperiod" double precision,
    "endperiod" double precision,
    "finalsummariesrun" smallint,
    "periodlocked" smallint DEFAULT 0 NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: tblperiodmonth; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tblperiodmonth" (
    "endmonth" double precision NOT NULL,
    "monthno" double precision NOT NULL
);


--
-- Name: tblkperiodmonth; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."tblkperiodmonth" AS
 SELECT "tblperiodmonth"."endmonth",
    "tblperiodmonth"."monthno",
    "tblperiod"."periodname",
    "tblperiod"."fpsyear"
   FROM ("fps"."tblperiod"
     JOIN "fps"."tblperiodmonth" ON (("tblperiod"."endperiod" = "tblperiodmonth"."endmonth")));


--
-- Name: qryrptahvggraph1; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qryrptahvggraph1" AS
 SELECT "monthlyoutput"."buyer",
    "tblkperiodmonth"."endmonth",
    "monthlyoutput"."testcode",
    "monthlyoutput"."fpsyear",
    "sum"("monthlyoutput"."volume") AS "actualvol"
   FROM ("fps"."tlkptestcapability"
     JOIN ("fps"."tblkperiodmonth"
     JOIN "fps"."monthlyoutput" ON ((("tblkperiodmonth"."monthno" = "monthlyoutput"."month") AND ("tblkperiodmonth"."fpsyear" = "monthlyoutput"."fpsyear")))) ON (((("tlkptestcapability"."workgroup")::"text" = ("monthlyoutput"."workgroup")::"text") AND (("tlkptestcapability"."testcode")::"text" = ("monthlyoutput"."testcode")::"text") AND ("tlkptestcapability"."fpsyear" = "monthlyoutput"."fpsyear"))))
  GROUP BY "monthlyoutput"."buyer", "tblkperiodmonth"."endmonth", "monthlyoutput"."testcode", "monthlyoutput"."fpsyear";


--
-- Name: qrytcc_union; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytcc_union" AS
 SELECT "workgroup"."workgroup",
    "tlkpproject"."parentproject" AS "project",
    "tlkpproject"."fpsyear"
   FROM ("fps"."workgroup"
     JOIN "fps"."tlkpproject" ON (("workgroup"."fpsyear" = "tlkpproject"."fpsyear")))
  WHERE (("workgroup"."workgroup")::"text" ~~ 'SV__'::"text")
UNION
 SELECT "timecostcalcs"."workgroup",
    "timecostcalcs"."project",
    "timecostcalcs"."fpsyear"
   FROM "fps"."timecostcalcs";


--
-- Name: qrysurvprojectsum; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrysurvprojectsum" AS
 SELECT DISTINCT "qrytcc_union"."project",
    "qrytcc_union"."workgroup",
    "tlkpjobcode"."type",
    "sum"("timecostcalcs"."cost") AS "hourscost",
    "timecostcalcs"."month",
    "timecostcalcs"."fpsyear"
   FROM ("fps"."qrytcc_union"
     LEFT JOIN ("fps"."tlkpjobcode"
     RIGHT JOIN "fps"."timecostcalcs" ON (((("tlkpjobcode"."parentproject")::"text" = ("timecostcalcs"."project")::"text") AND (("tlkpjobcode"."jobcode")::"text" = ("timecostcalcs"."jobcode")::"text") AND ("tlkpjobcode"."fpsyear" = "timecostcalcs"."fpsyear")))) ON (((("qrytcc_union"."project")::"text" = ("timecostcalcs"."project")::"text") AND (("qrytcc_union"."workgroup")::"text" = ("timecostcalcs"."workgroup")::"text") AND ("qrytcc_union"."fpsyear" = "timecostcalcs"."fpsyear"))))
  GROUP BY "qrytcc_union"."project", "qrytcc_union"."workgroup", "tlkpjobcode"."type", "timecostcalcs"."month", "timecostcalcs"."fpsyear";


--
-- Name: tbltestrccost; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tbltestrccost" (
    "testcode" character varying(20) NOT NULL,
    "profitcentre" character varying(50) NOT NULL,
    "price" "money" DEFAULT 0 NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: vtbltestrequ_tm; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vtbltestrequ_tm" AS
 SELECT "buyer" AS "jobcode",
    "testcode",
    "norequired" AS "notests",
    "unitprice" AS "testprice",
    "fpsyear"
   FROM "fps"."tlkptestreqmt";


--
-- Name: qrytestpcccostplan; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytestpcccostplan" AS
 SELECT "vtbltestrequ_tm"."jobcode",
    "vtbltestrequ_tm"."testcode",
    "tbltestrccost"."profitcentre",
    ("tbltestrccost"."price")::numeric AS "price",
    "vtbltestrequ_tm"."fpsyear"
   FROM ("fps"."vtbltestrequ_tm"
     LEFT JOIN "fps"."tbltestrccost" ON (((("vtbltestrequ_tm"."testcode")::"text" = ("tbltestrccost"."testcode")::"text") AND ("vtbltestrequ_tm"."fpsyear" = "tbltestrccost"."fpsyear"))))
  WHERE (("tbltestrccost"."price" IS NOT NULL) AND ("tbltestrccost"."profitcentre" IS NOT NULL))
  ORDER BY "vtbltestrequ_tm"."jobcode";


--
-- Name: tbltestrequirementrccost; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tbltestrequirementrccost" (
    "testcode" character varying(20) NOT NULL,
    "buyer" character varying(20) NOT NULL,
    "profitcentre" character varying(50) NOT NULL,
    "price" "money" NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: qrytestspccostplan_crosstab; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytestspccostplan_crosstab" AS
 SELECT "qrytestpcccostplan"."jobcode",
    "qrytestpcccostplan"."testcode",
    "qrytestpcccostplan"."profitcentre",
    "qrytestpcccostplan"."fpsyear",
        CASE "qrytestpcccostplan"."profitcentre"
            WHEN 'LabT'::"text" THEN "max"(COALESCE(("tbltestrequirementrccost"."price")::numeric, "qrytestpcccostplan"."price"))
            ELSE (0)::numeric
        END AS "labt",
        CASE "qrytestpcccostplan"."profitcentre"
            WHEN 'VSD GB'::"text" THEN "max"(COALESCE(("tbltestrequirementrccost"."price")::numeric, "qrytestpcccostplan"."price"))
            ELSE (0)::numeric
        END AS "vetr",
        CASE "qrytestpcccostplan"."profitcentre"
            WHEN 'Viro'::"text" THEN "max"(COALESCE(("tbltestrequirementrccost"."price")::numeric, "qrytestpcccostplan"."price"))
            ELSE (0)::numeric
        END AS "viro"
   FROM ("fps"."qrytestpcccostplan"
     LEFT JOIN "fps"."tbltestrequirementrccost" ON (((("qrytestpcccostplan"."profitcentre")::"text" = ("tbltestrequirementrccost"."profitcentre")::"text") AND (("qrytestpcccostplan"."jobcode")::"text" = ("tbltestrequirementrccost"."buyer")::"text") AND (("qrytestpcccostplan"."testcode")::"text" = ("tbltestrequirementrccost"."testcode")::"text") AND ("qrytestpcccostplan"."fpsyear" = "tbltestrequirementrccost"."fpsyear"))))
  GROUP BY "qrytestpcccostplan"."jobcode", "qrytestpcccostplan"."testcode", "qrytestpcccostplan"."profitcentre", "qrytestpcccostplan"."fpsyear"
  ORDER BY "qrytestpcccostplan"."jobcode";


--
-- Name: qrytestspccostplan_xtab; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytestspccostplan_xtab" AS
 SELECT "testcode",
    "fpsyear",
    "sum"(
        CASE "profitcentre"
            WHEN 'LabT'::"text" THEN ("price")::numeric
            ELSE (0)::numeric
        END) AS "labt",
    "sum"(
        CASE "profitcentre"
            WHEN 'VSD GB'::"text" THEN ("price")::numeric
            ELSE (0)::numeric
        END) AS "vetr",
    "sum"(
        CASE "profitcentre"
            WHEN 'Viro'::"text" THEN ("price")::numeric
            ELSE (0)::numeric
        END) AS "viro"
   FROM "fps"."tbltestrccost"
  GROUP BY "testcode", "fpsyear";


--
-- Name: qrytestspcostplan_xtab; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytestspcostplan_xtab" AS
 SELECT "testcode",
    "sum"(
        CASE "lower"(("profitcentre")::"text")
            WHEN 'labt'::"text" THEN "price"
            ELSE (0)::"money"
        END) AS "labt",
    "sum"(
        CASE "lower"(("profitcentre")::"text")
            WHEN 'vsd gb'::"text" THEN "price"
            ELSE (0)::"money"
        END) AS "vetr",
    "sum"(
        CASE "lower"(("profitcentre")::"text")
            WHEN 'viro'::"text" THEN "price"
            ELSE (0)::"money"
        END) AS "viro"
   FROM "fps"."tbltestrccost"
  GROUP BY "testcode";


