    "indcounter" integer NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: tblanimals; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tblanimals" (
    "animaltype" character varying(50) NOT NULL,
    "species" character varying(50),
    "security_level" character varying(50),
    "dailyrate" "money",
    "planbyweek" boolean DEFAULT false NOT NULL,
    "defradailyrate" "money",
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: vprojectanimalplan; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vprojectanimalplan" AS
 SELECT "tlkpproject"."parentproject",
    "tlkpproject"."program",
    "tblanimalreq"."animaltype",
    "tblanimalreq"."numberofdays",
    "tblanimalreq"."numberofanimals",
        CASE "tlkpproject"."isdefraproject"
            WHEN 0 THEN "tblanimals"."dailyrate"
            ELSE "tblanimals"."defradailyrate"
        END AS "dailyrate",
    (("tblanimalreq"."numberofanimals" * "tblanimalreq"."numberofdays") *
        CASE "tlkpproject"."isdefraproject"
            WHEN 0 THEN "tblanimals"."dailyrate"
            ELSE "tblanimals"."defradailyrate"
        END) AS "cost",
    "tblanimals"."species",
    "tblanimals"."security_level",
    "tblanimalreq"."indcounter",
    "tblanimalreq"."fpsyear"
   FROM (("fps"."tlkpproject"
     JOIN "fps"."tblanimalreq" ON (((("tlkpproject"."parentproject")::"text" = ("tblanimalreq"."jobcode")::"text") AND ("tlkpproject"."fpsyear" = "tblanimalreq"."fpsyear"))))
     JOIN "fps"."tblanimals" ON (((("tblanimalreq"."animaltype")::"text" = ("tblanimals"."animaltype")::"text") AND ("tblanimalreq"."fpsyear" = "tblanimals"."fpsyear"))));


--
-- Name: qrytotalanimalcosts; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytotalanimalcosts" AS
 SELECT DISTINCT "parentproject" AS "jobcode",
    "fpsyear",
    "sum"("cost") AS "totalanimalcosts"
   FROM "fps"."vprojectanimalplan"
  GROUP BY "parentproject", "fpsyear";


--
-- Name: tblemployee; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tblemployee" (
    "spnumber" character varying(10) NOT NULL,
    "firstname" character varying(20),
    "lastname" character varying(20),
    "title" character varying(4),
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: vprojectstaffplan; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vprojectstaffplan" AS
 SELECT "tlkpproject"."parentproject",
    "tlkpprogram"."programno",
    "tlkpproject"."contract",
    (((COALESCE("tblemployee"."lastname", ''::character varying))::"text" || ', '::"text") || (COALESCE("tblemployee"."firstname", ''::character varying))::"text") AS "name",
    "tblstaffjob"."staffid",
    "tblstaffjob"."plannedhours",
        CASE "tlkpproject"."isdefraproject"
            WHEN 0 THEN "profitcentregrade"."chargerate"
            ELSE "profitcentregrade"."defrachargerate"
        END AS "chargerate",
    (("tblstaffjob"."plannedhours" * (
        CASE "lower"(("tlkpprogram"."sector_name")::"text")
            WHEN 'charge'::"text" THEN (1)::numeric
            ELSE (0)::numeric
        END)::double precision) *
        CASE "tlkpproject"."isdefraproject"
            WHEN 0 THEN "profitcentregrade"."chargerate"
            ELSE "profitcentregrade"."defrachargerate"
        END) AS "cost",
    (("tblstaffjob"."plannedhours" * (
        CASE "lower"(("tlkpprogram"."sector_name")::"text")
            WHEN 'charge'::"text" THEN (1)::numeric
            ELSE (0)::numeric
        END)::double precision) * "profitcentregrade"."payrate") AS "paycost",
    "profitcentregrade"."profitcentre",
    "workgroupgrade"."workgroup",
    "workgroupgrade"."wggrade",
    "profitcentregrade"."pcgrade",
    "workgroupgrade"."gradecode",
    "tblwgemployee"."fpsyear"
   FROM (((((("fps"."tblwgemployee"
     JOIN "fps"."tblstaffjob" ON (((("tblwgemployee"."pactid")::"text" = ("tblstaffjob"."staffid")::"text") AND ("tblwgemployee"."fpsyear" = "tblstaffjob"."fpsyear"))))
     JOIN "fps"."tblemployee" ON (((("tblwgemployee"."spnumber")::"text" = ("tblemployee"."spnumber")::"text") AND ("tblwgemployee"."fpsyear" = "tblemployee"."fpsyear"))))
     JOIN "fps"."workgroupgrade" ON (((("tblwgemployee"."workgroupgrade")::"text" = ("workgroupgrade"."wggrade")::"text") AND ("tblwgemployee"."fpsyear" = "workgroupgrade"."fpsyear"))))
     JOIN "fps"."profitcentregrade" ON (((("workgroupgrade"."profitcentregrade")::"text" = ("profitcentregrade"."pcgrade")::"text") AND ("workgroupgrade"."fpsyear" = "profitcentregrade"."fpsyear"))))
     JOIN "fps"."tlkpproject" ON (((("tblstaffjob"."jobcode")::"text" = ("tlkpproject"."parentproject")::"text") AND ("tblstaffjob"."fpsyear" = "tlkpproject"."fpsyear"))))
     JOIN "fps"."tlkpprogram" ON (((("tlkpproject"."program")::"text" = ("tlkpprogram"."programno")::"text") AND ("tlkpproject"."fpsyear" = "tlkpprogram"."fpsyear"))));


--
-- Name: qrytotalstaffcosts; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytotalstaffcosts" AS
 SELECT DISTINCT "parentproject" AS "jobcode",
    "fpsyear",
    "sum"("cost") AS "totalstaffcosts",
    "sum"("paycost") AS "totalpaycosts"
   FROM "fps"."vprojectstaffplan"
  GROUP BY "parentproject", "fpsyear";


--
-- Name: tbluser_program; Type: TABLE; Schema: fps; Owner: -
--

CREATE TABLE "fps"."tbluser_program" (
    "user_id" integer NOT NULL,
    "programno" character varying(10) NOT NULL,
    "fpsyear" integer NOT NULL
)
PARTITION BY LIST ("fpsyear");


--
-- Name: vtbltestrequ; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vtbltestrequ" AS
 SELECT DISTINCT "tr"."buyer" AS "jobcode",
    "tr"."testcode",
    "tr"."norequired" AS "notests",
    "tr"."unitprice" AS "testprice",
    "tr"."datecreated",
    "tr"."projectbuyercode",
    "tr"."fpsyear",
    "u"."user_id",
    "u"."dt2username",
    "u"."useremail"
   FROM (((("fps"."tlkptestreqmt" "tr"
     JOIN "fps"."tlkpproject" "pj" ON ((("tr"."buyer")::"text" = ("pj"."parentproject")::"text")))
     JOIN "fps"."tlkpprogram" "pg" ON ((("pj"."program")::"text" = ("pg"."programno")::"text")))
     JOIN "fps"."tbluser_program" "up" ON ((("pg"."programno")::"text" = ("up"."programno")::"text")))
     JOIN "fps"."tblusers" "u" ON (("up"."user_id" = "u"."user_id")));


--
-- Name: qrytotaltestcosts; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qrytotaltestcosts" AS
 SELECT "jobcode",
    "sum"(("notests" * "testprice")) AS "totaltestcosts"
   FROM "fps"."vtbltestrequ"
  GROUP BY "jobcode";


--
-- Name: vplancrosstab; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vplancrosstab" AS
 SELECT "jobcode",
    "testcode",
    "fpsyear",
    "sum"("labt") AS "labt",
    "sum"("vetr") AS "vetr",
    "sum"("viro") AS "viro"
   FROM "fps"."qrytestspccostplan_crosstab"
  GROUP BY "jobcode", "testcode", "fpsyear";


--
-- Name: qvrd_split; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qvrd_split" AS
 SELECT "monthlyoutput"."workgroup" AS "location",
    "monthlyoutput"."month",
    ((
        CASE "vplancrosstab"."vetr"
            WHEN 0 THEN (1)::numeric
            ELSE (0)::numeric
        END)::double precision * (("vplancrosstab"."labt")::double precision * "sum"("monthlyoutput"."volume"))) AS "ltsplitfee",
        CASE "vplancrosstab"."vetr"
            WHEN 0 THEN (1)::numeric
            ELSE (0)::numeric
        END AS "ispartofltfee",
    "monthlyoutput"."testcode",
    "monthlyoutput"."fpsyear",
    "sum"("monthlyoutput"."volume") AS "totvol",
    "vplancrosstab"."labt" AS "ltunitcharge",
    "vplancrosstab"."vetr" AS "sdunitcharge",
    (("vplancrosstab"."labt")::double precision * "sum"("monthlyoutput"."volume")) AS "ltfee",
    (("vplancrosstab"."vetr")::double precision * "sum"("monthlyoutput"."volume")) AS "sdfee",
    ((("vplancrosstab"."labt")::double precision * "sum"("monthlyoutput"."volume")) + (("vplancrosstab"."vetr")::double precision * "sum"("monthlyoutput"."volume"))) AS "totalfee",
    (((("tlkptestreqmt"."unitprice")::numeric)::double precision * "sum"("monthlyoutput"."volume")) - ((("vplancrosstab"."labt")::double precision * "sum"("monthlyoutput"."volume")) + (("vplancrosstab"."vetr")::double precision * "sum"("monthlyoutput"."volume")))) AS "profit/loss",
    ("tlkptestreqmt"."unitprice")::numeric AS "testprice"
   FROM ((("fps"."monthlyoutput"
     JOIN "fps"."tlkptestcapability" ON (((("monthlyoutput"."testcode")::"text" = ("tlkptestcapability"."testcode")::"text") AND (("monthlyoutput"."workgroup")::"text" = ("tlkptestcapability"."workgroup")::"text") AND ("monthlyoutput"."fpsyear" = "tlkptestcapability"."fpsyear"))))
     JOIN "fps"."vplancrosstab" ON (((("monthlyoutput"."testcode")::"text" = ("vplancrosstab"."testcode")::"text") AND ("monthlyoutput"."fpsyear" = "vplancrosstab"."fpsyear"))))
     JOIN "fps"."tlkptestreqmt" ON (((("monthlyoutput"."testcode")::"text" = ("tlkptestreqmt"."testcode")::"text") AND (("monthlyoutput"."buyer")::"text" = ("tlkptestreqmt"."buyer")::"text") AND ("monthlyoutput"."fpsyear" = "tlkptestreqmt"."fpsyear"))))
  GROUP BY "vplancrosstab"."labt", "vplancrosstab"."vetr", "monthlyoutput"."workgroup", "monthlyoutput"."month", "monthlyoutput"."testcode", "tlkptestcapability"."planportfolio", (("tlkptestreqmt"."unitprice")::numeric), "monthlyoutput"."fpsyear"
 HAVING ((("tlkptestcapability"."planportfolio")::"text" = 'TG0100'::"text") AND ("monthlyoutput"."month" <= ( SELECT "max"("tblperiod"."endperiod") AS "month"
           FROM "fps"."tblperiod"
          WHERE ("tblperiod"."finalsummariesrun" = '-1'::integer))) AND ("vplancrosstab"."labt" IS NOT NULL) AND ("vplancrosstab"."vetr" IS NOT NULL))
  ORDER BY "monthlyoutput"."workgroup", "monthlyoutput"."month", "monthlyoutput"."testcode";


--
-- Name: vpostmort_vrd_split; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vpostmort_vrd_split" AS
 SELECT "right"(("monthlyoutput"."workgroup")::"text", 2) AS "location",
    "monthlyoutput"."month",
    ((((
        CASE "qrytestspccostplan_xtab"."vetr"
            WHEN 0 THEN 0
            WHEN NULL::numeric THEN 0
            ELSE 1
        END)::numeric * "qrytestspccostplan_xtab"."labt"))::double precision * "sum"("monthlyoutput"."volume")) AS "ltsplitfee",
        CASE "qrytestspccostplan_xtab"."vetr"
            WHEN 0 THEN 0
            WHEN NULL::numeric THEN 0
            ELSE 1
        END AS "ispartofltfee",
    "monthlyoutput"."testcode",
    "monthlyoutput"."fpsyear",
    "sum"("monthlyoutput"."volume") AS "totvol",
    "qrytestspccostplan_xtab"."labt" AS "ltunitcharge",
    "qrytestspccostplan_xtab"."vetr" AS "sdunitcharge",
    (("qrytestspccostplan_xtab"."labt")::double precision * "sum"("monthlyoutput"."volume")) AS "ltfee",
    (("qrytestspccostplan_xtab"."vetr")::double precision * "sum"("monthlyoutput"."volume")) AS "sdfee",
    ((("qrytestspccostplan_xtab"."labt")::double precision * "sum"("monthlyoutput"."volume")) + (("qrytestspccostplan_xtab"."vetr")::double precision * "sum"("monthlyoutput"."volume"))) AS "totalfee",
    (((("tlkptestreqmt"."unitprice")::numeric)::double precision * "sum"("monthlyoutput"."volume")) - ((("qrytestspccostplan_xtab"."labt")::double precision * "sum"("monthlyoutput"."volume")) + (("qrytestspccostplan_xtab"."vetr")::double precision * "sum"("monthlyoutput"."volume")))) AS "profit/loss",
    ("tlkptestreqmt"."unitprice")::numeric AS "unitprice"
   FROM ((("fps"."monthlyoutput"
     JOIN "fps"."tlkptestcapability" ON (((("monthlyoutput"."testcode")::"text" = ("tlkptestcapability"."testcode")::"text") AND (("monthlyoutput"."workgroup")::"text" = ("tlkptestcapability"."workgroup")::"text") AND ("monthlyoutput"."fpsyear" = "tlkptestcapability"."fpsyear"))))
     JOIN "fps"."qrytestspccostplan_xtab" ON (((("monthlyoutput"."testcode")::"text" = ("qrytestspccostplan_xtab"."testcode")::"text") AND ("monthlyoutput"."fpsyear" = "qrytestspccostplan_xtab"."fpsyear"))))
     JOIN "fps"."tlkptestreqmt" ON (((("monthlyoutput"."testcode")::"text" = ("tlkptestreqmt"."testcode")::"text") AND (("monthlyoutput"."buyer")::"text" = ("tlkptestreqmt"."buyer")::"text") AND ("monthlyoutput"."fpsyear" = "tlkptestreqmt"."fpsyear"))))
  GROUP BY "qrytestspccostplan_xtab"."labt", "qrytestspccostplan_xtab"."vetr", "monthlyoutput"."workgroup", "monthlyoutput"."month", "monthlyoutput"."testcode", "tlkptestcapability"."planportfolio", (("tlkptestreqmt"."unitprice")::numeric), "monthlyoutput"."fpsyear"
 HAVING (("lower"(("tlkptestcapability"."planportfolio")::"text") = ANY (ARRAY['tg0100'::"text", 'pmport1'::"text"])) AND ("monthlyoutput"."month" <= ( SELECT "max"("tblperiod"."endperiod") AS "month"
           FROM "fps"."tblperiod"
          WHERE ("tblperiod"."finalsummariesrun" = '-1'::integer))))
  ORDER BY ("right"(("monthlyoutput"."workgroup")::"text", 2)), "monthlyoutput"."month", "monthlyoutput"."testcode";


--
-- Name: qvrd_splitlocationmonthly; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qvrd_splitlocationmonthly" AS
 SELECT "location",
    "month",
    "fpsyear",
    "sum"("ltsplitfee") AS "labltsplitfee"
   FROM "fps"."vpostmort_vrd_split"
  GROUP BY "location", "month", "fpsyear"
  ORDER BY "location", "month";


--
-- Name: qvrd_splitmonthly; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."qvrd_splitmonthly" AS
 SELECT "month",
    "fpsyear",
    "sum"("ltsplitfee") AS "totalltsplitfee"
   FROM "fps"."vpostmort_vrd_split"
  GROUP BY "month", "fpsyear";


