    "c"."customer",
    "c"."title",
    "c"."registereddate",
    "c"."startdate",
    "c"."enddate",
    "c"."contractdoc",
    "c"."duration",
    "c"."fpsyear",
    "u"."user_id",
    "u"."dt2username",
    "u"."useremail"
   FROM (("fps"."tblcontract" "c"
     JOIN "fps"."tbluser_category" "uc" ON ((("c"."category")::"text" = ("uc"."category")::"text")))
     JOIN "fps"."tblusers" "u" ON (("uc"."user_id" = "u"."user_id")));


