--
-- Name: vcurrentperiod; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vcurrentperiod" AS
 SELECT "periodname",
    "fpsyear"
   FROM "fps"."tblperiod"
  WHERE ("endperiod" = ( SELECT "max"("tblperiod_1"."endperiod") AS "maxendperiod"
           FROM "fps"."tblperiod" "tblperiod_1"
          GROUP BY "tblperiod_1"."finalsummariesrun"
         HAVING ("tblperiod_1"."finalsummariesrun" = '-1'::integer)));


--
-- Name: vcustomerbudgetbyprogram; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vcustomerbudgetbyprogram" AS
 SELECT "program",
    "projectstatus",
    "customer",
    "fpsyear",
    "sum"("budget_cvl") AS "customerbudget"
   FROM "fps"."tlkpproject"
  GROUP BY "program", "projectstatus", "customer", "fpsyear";


--
-- Name: vfthours; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vfthours" AS
 SELECT (1.0 * ( SELECT ("tblsettings"."setting")::numeric AS "setting"
           FROM "fps"."tblsettings"
          WHERE (("tblsettings"."id")::"text" = 'HoursInDay'::"text"))) AS "fthoursperday",
    (5.0 * ( SELECT ("tblsettings_1"."setting")::numeric AS "setting"
           FROM "fps"."tblsettings" "tblsettings_1"
          WHERE (("tblsettings_1"."id")::"text" = 'HoursInDay'::"text"))) AS "fthoursperweek",
    ( SELECT "sum"("tlkpmonthhours"."cvlhours") AS "fthourspaid"
           FROM "fps"."tlkpmonthhours"
          WHERE ((NOT (("tlkpmonthhours"."year")::"text" = ( SELECT "right"(("tbldb_variables"."db_var_value")::"text", 4) AS "expr1"
                   FROM "fps"."tbldb_variables"
                  WHERE (("tbldb_variables"."db_var_name")::"text" = 'DB_Name'::"text")))) OR (NOT ("tlkpmonthhours"."month" < 4)))) AS "fthourspaidperyear";


--
-- Name: view3; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."view3" AS
 SELECT "timecostcalcs"."project",
    "timecostcalcs"."jobcode",
    "timecostcalcs"."fpsyear",
    "sum"("timecostcalcs"."cost") AS "sumofcost",
        CASE "workgroup"."profitcentre"
            WHEN 'Path'::"text" THEN 'Surveillance/Pathology'::"text"
            WHEN 'vetr'::"text" THEN 'Surveillance/Pathology'::"text"
            ELSE 'Laboratory Testing'::"text"
        END AS "resourcecentre"
   FROM ("fps"."timecostcalcs"
     JOIN "fps"."workgroup" ON (((("timecostcalcs"."workgroup")::"text" = ("workgroup"."workgroup")::"text") AND ("timecostcalcs"."fpsyear" = "workgroup"."fpsyear"))))
  GROUP BY "workgroup"."profitcentre", "timecostcalcs"."project", "timecostcalcs"."jobcode", "timecostcalcs"."fpsyear",
        CASE "workgroup"."profitcentre"
            WHEN 'Path'::"text" THEN 'Surveillance/Pathology'::"text"
            WHEN 'vetr'::"text" THEN 'Surveillance/Pathology'::"text"
            ELSE 'Laboratory Testing'::"text"
        END
 HAVING ((("timecostcalcs"."project")::"text" = 'TG0100'::"text") AND ("max"("timecostcalcs"."month") <= ( SELECT "max"("tblperiod"."endperiod") AS "endperiod"
           FROM "fps"."tblperiod"
          WHERE ("tblperiod"."finalsummariesrun" = '-1'::integer))));


