    "sum"("cumcoiw") AS "cumcoiw",
    "sum"("cumportsales") AS "cumportsales",
    "sum"("mstonedue") AS "mstonedue",
    "sum"("due__done") AS "due__done",
    "sum"("ontime") AS "ontime",
    "sum"("sumofmstonedue") AS "sumofmstonedue",
    "sum"("sumofdue__done") AS "sumofdue__done",
