--
-- Name: vvrd_split; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vvrd_split" AS
 SELECT "qvrd_splitlocationmonthly"."location",
    "qvrd_splitlocationmonthly"."fpsyear",
    "sum"(("qvrd_splitlocationmonthly"."labltsplitfee" / "qvrd_splitmonthly"."totalltsplitfee")) AS "split"
   FROM ("fps"."qvrd_splitmonthly"
     JOIN "fps"."qvrd_splitlocationmonthly" ON ((("qvrd_splitmonthly"."month" = "qvrd_splitlocationmonthly"."month") AND ("qvrd_splitmonthly"."fpsyear" = "qvrd_splitlocationmonthly"."fpsyear"))))
  GROUP BY "qvrd_splitlocationmonthly"."location", "qvrd_splitlocationmonthly"."fpsyear"
  ORDER BY "qvrd_splitlocationmonthly"."location";


--
-- Name: vvrd_splitlocation; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vvrd_splitlocation" AS
 SELECT "qvrd_splitlocationmonthly"."location",
    "qvrd_splitlocationmonthly"."fpsyear",
    "sum"(("qvrd_splitlocationmonthly"."labltsplitfee" / "qvrd_splitmonthly"."totalltsplitfee")) AS "splitmultiplier"
   FROM ("fps"."qvrd_splitlocationmonthly"
     JOIN "fps"."qvrd_splitmonthly" ON ((("qvrd_splitlocationmonthly"."month" = "qvrd_splitmonthly"."month") AND ("qvrd_splitlocationmonthly"."fpsyear" = "qvrd_splitmonthly"."fpsyear"))))
  GROUP BY "qvrd_splitlocationmonthly"."location", "qvrd_splitlocationmonthly"."fpsyear";


--
-- Name: vwgjobcodes; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vwgjobcodes" AS
 SELECT DISTINCT "tlkpproject"."parentproject",
    "timecodevalid"."timecode",
    "timecodevalid"."workgroup",
    "tlkpproject"."fpsyear",
    (((("tlkpproject"."shorttitle")::"text" || ': '::"text") || ("tlkpjobcode"."jobcodename")::"text") || ("testorproduct"."itemdescription")::"text") AS "descript"
   FROM ((("fps"."tlkpproject"
     JOIN "fps"."timecodevalid" ON (((("tlkpproject"."parentproject")::"text" = ("timecodevalid"."parentproject")::"text") AND ("tlkpproject"."fpsyear" = "timecodevalid"."fpsyear"))))
     LEFT JOIN "fps"."tlkpjobcode" ON (((("timecodevalid"."parentproject")::"text" = ("tlkpjobcode"."parentproject")::"text") AND (("timecodevalid"."jobcode")::"text" = ("tlkpjobcode"."jobcode")::"text") AND ("timecodevalid"."fpsyear" = "tlkpjobcode"."fpsyear"))))
     LEFT JOIN "fps"."testorproduct" ON (((("timecodevalid"."testcode")::"text" = ("testorproduct"."itemcode")::"text") AND ("timecodevalid"."fpsyear" = "testorproduct"."fpsyear"))));


--
-- Name: vwinvoicebymonth; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vwinvoicebymonth" AS
 SELECT "proj"."fpsyear",
    "proj"."program",
    "proj"."parentproject",
    "sum"("projinv"."amount") AS "monthlyamount",
    "projinv"."month"
   FROM ("fps"."tlkpproject" "proj"
     JOIN "fps"."proj_invoice" "projinv" ON (((("proj"."parentproject")::"text" = ("projinv"."projectparent")::"text") AND ("proj"."fpsyear" = "projinv"."fpsyear"))))
  GROUP BY "proj"."fpsyear", "proj"."program", "proj"."parentproject", "projinv"."month";


