CREATE VIEW "fps"."vwsubcontractbymonth" AS
 SELECT "proj"."fpsyear",
    "proj"."program",
    "proj"."parentproject",
    "sum"("projsubcontract"."amount") AS "monthlyamount",
    "projsubcontract"."month"
   FROM ("fps"."tlkpproject" "proj"
     JOIN "fps"."proj_subcontract" "projsubcontract" ON (((("proj"."parentproject")::"text" = ("projsubcontract"."project")::"text") AND ("proj"."fpsyear" = "projsubcontract"."fpsyear"))))
  GROUP BY "proj"."fpsyear", "proj"."program", "proj"."parentproject", "projsubcontract"."month";


--
-- Name: vwsummarisedstafftimeusage; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vwsummarisedstafftimeusage" AS
 SELECT "wg"."fpsyear",
    "m"."monthname",
    "wg"."profitcentre",
    "wg"."workgroup",
    "wgg"."wg_grade",
    "s"."name",
    "s"."hrspaid",
    "j"."parentproject",
    "tc"."jobcode",
        CASE
            WHEN ("j"."jobcode" IS NULL) THEN "tp"."itemdescription"
            ELSE "j"."jobcodename"
        END AS "jobtitle",
        CASE
            WHEN ("tc"."cost" = (0)::double precision) THEN 0
            ELSE 1
        END AS "utflag",
    "sum"("tc"."time") AS "totaltime",
    "sum"("tc"."cost") AS "totalcost"
   FROM (((((("fps"."workgroup" "wg"
     JOIN "fps"."vpactworkgroupgrade" "wgg" ON (((("wg"."workgroup")::"text" = ("wgg"."workgroup")::"text") AND ("wg"."fpsyear" = "wgg"."fpsyear"))))
     JOIN "fps"."vpacttblstaff" "s" ON (((("wgg"."wg_grade")::"text" = ("s"."workgroupgrade")::"text") AND ("wgg"."fpsyear" = "s"."fpsyear"))))
     JOIN "fps"."timecostcalcs" "tc" ON (((("s"."pactid")::"text" = ("tc"."staffid")::"text") AND ("s"."fpsyear" = "tc"."fpsyear"))))
     JOIN "fps"."tlkpmonth" "m" ON ((("m"."accntsperiod")::double precision = "tc"."month")))
     LEFT JOIN "fps"."tlkpjobcode" "j" ON (((("tc"."jobcode")::"text" = ("j"."jobcode")::"text") AND ("tc"."fpsyear" = "j"."fpsyear"))))
     LEFT JOIN "fps"."vpacttestorproduct" "tp" ON (((("tc"."jobcode")::"text" = ("tp"."itemcode")::"text") AND ("j"."fpsyear" = "tp"."fpsyear"))))
  GROUP BY "wg"."fpsyear", "m"."monthname", "wg"."profitcentre", "wg"."workgroup", "wgg"."wg_grade", "s"."name", "s"."hrspaid", "j"."parentproject", "tc"."jobcode",
        CASE
            WHEN ("j"."jobcode" IS NULL) THEN "tp"."itemdescription"
            ELSE "j"."jobcodename"
        END,
        CASE
            WHEN ("tc"."cost" = (0)::double precision) THEN 0
            ELSE 1
        END;


--
-- Name: vwsummarisedwgtimeusage; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."vwsummarisedwgtimeusage" AS
 SELECT "wg"."fpsyear",
    "m"."monthname",
    "wg"."profitcentre",
    "wg"."workgroup",
    "p"."parentproject",
    "p"."projecttitle",
    "sum"("tc"."time") AS "totaltime",
    "sum"("tc"."cost") AS "totalcost"
   FROM ((((("fps"."workgroup" "wg"
     JOIN "fps"."vpactworkgroupgrade" "wgg" ON (((("wg"."workgroup")::"text" = ("wgg"."workgroup")::"text") AND ("wg"."fpsyear" = "wgg"."fpsyear"))))
     JOIN "fps"."vpacttblstaff" "s" ON (((("wgg"."wg_grade")::"text" = ("s"."workgroupgrade")::"text") AND ("wgg"."fpsyear" = "s"."fpsyear"))))
     JOIN "fps"."timecostcalcs" "tc" ON (((("s"."pactid")::"text" = ("tc"."staffid")::"text") AND ("s"."fpsyear" = "tc"."fpsyear"))))
     JOIN "fps"."tlkpmonth" "m" ON ((("m"."accntsperiod")::double precision = "tc"."month")))
     JOIN "fps"."tlkpproject" "p" ON (((("p"."parentproject")::"text" = ("tc"."project")::"text") AND ("tc"."fpsyear" = "p"."fpsyear"))))
  GROUP BY "wg"."fpsyear", "wg"."profitcentre", "wg"."workgroup", "p"."parentproject", "p"."projecttitle", "m"."monthname";


