--
-- Name: xxtestorproduct_tm; Type: VIEW; Schema: fps; Owner: -
--

CREATE VIEW "fps"."xxtestorproduct_tm" AS
 SELECT DISTINCT "tp"."itemcode",
    "tp"."itemdescription",
    "tp"."testmanager",
    "tp"."jobstatus",
    "tp"."unitpricevla",
    "tp"."priceahvg",
    "tp"."owner",
    "tp"."chargemethod",
    "tp"."shortdescription",
    "tp"."defraunitprice",
    "tp"."fpsyear",
    "u"."username",
    "u"."user_id",
    "u"."dt2username",
    "u"."useremail"
   FROM (("fps"."testorproduct" "tp"
     JOIN "fps"."tbluser_testowner" "uto" ON ((("tp"."owner")::"text" = ("uto"."test_owner")::"text")))
     JOIN "fps"."tblusers" "u" ON (("uto"."user_id" = "u"."user_id")));


